    36|/** True when Twilio or SignalWire has enough config to attempt a send. */
    37|export function isTwilioSmsConfigured(): boolean {
    38|  const accountSid = readEnv('IVX_TWILIO_ACCOUNT_SID');
    39|  const authToken = readEnv('IVX_TWILIO_AUTH_TOKEN');
    40|  const apiKeySid = readEnv('IVX_TWILIO_API_KEY_SID');
