    42|  const authMode = Boolean(accountSid && authToken);
    43|  const keyMode = Boolean(accountSid && apiKeySid && apiKeySecret);
    44|  return authMode || keyMode;
    45|}
    46|
    47|function resolveApiHost(): { host: string; provider: 'twilio' | 'signalwire' } {
    48|  const customHost = readEnv('IVX_TWILIO_API_HOST');
    49|  if (customHost) {
    50|    const normalized = customHost.replace(/^https?:\/\//, '').replace(/\/$/, '');
    51|    return {
    52|      host: `https://${normalized}`,
    53|      provider: normalized.toLowerCase().endsWith('signalwire.com') ? 'signalwire' : 'twilio',
    54|    };
    55|  }
    56|  return { host: 'https://api.twilio.com', provider: 'twilio' };
    57|}
